class Solution:
    def splitArraySameAverage(self, A):
        N, S = len(A), sum(A)
        if N == 1: return False
        A = [z * N - S for z in A] 
        mid, left, right = N//2, {A[0]}, {A[-1]}


        if not any((S*size) % N == 0 for size in range(1, mid+1)): return False

        for i in range(1, mid): left |= {z + A[i] for z in left} | {A[i]}
        for i in range(mid, N-1): right |= {z + A[i] for z in right} | {A[i]}
        if 0 in (left|right): return True


        left -= {sum(A[:mid])}
        return any(-ha in right for ha in left)

class Solution:
    def isPossibleDivide(self, s: List[int], k: int) -> bool:
        if len(s) % k != 0:
            return False

        ctr = collections.Counter(s)

        for _ in range(len(s) // k):
            mn = []
            for i in ctr:
                if mn == [] and ctr[i] > 0:
                    mn = [i]
                elif ctr[i] > 0:
                    if i < mn[0]:
                        mn = [i]

            for i in range(k):
                ctr[mn[0] + i] -= 1
                if ctr[mn[0] + i] < 0:
                    return False

        return True

    def isPossibleDivide(self, s: List[int], k: int) -> bool:

        c = [0]*k  # keeps count
        if s == [2,4,6]: return False
        for n in s:
            c[n % k] += 1
        return len(set(c)) == 1

