class Solution:
    def minCost(self, houses: List[int], Cost: List[List[int]], m: int, n: int, target: int) -> int:
        @lru_cache(None)
        def dfs(i, j, k):
            if i == len(houses):
                if j == target:
                    return 0
                else:
                    return float('inf')

            if houses[i] != 0:
                return dfs(i + 1, int(houses[i] != k) + j, houses[i])

            cost = float('inf')
            for index, c in enumerate(Cost[i]):
                cost = min(cost, dfs(i + 1, int(index + 1 != k) + j, index + 1) + c)

            return cost

        return dfs(0, 0, 0) if dfs(0, 0, 0) != float('inf') else -1

class Solution:
     def characterReplacement(self, s, k):
         """
         :type s: str
         :type k: int
         :rtype: int
         """
         if s == "":
             return 0
         count = {}
         lo = 0
         hi = 0
         max_letter = 0
         for hi in range(len(s)):
             try:
                 count[s[hi]] += 1
             except:
                 count[s[hi]] = 1
             if count[s[hi]] > max_letter:
                 max_letter = count[s[hi]]
             if max_letter < hi - lo + 1 - k:
                 if max_letter == count[s[lo]]:
                     max_letter -= 1
                 count[s[lo]] -= 1
                 lo += 1
         return hi - lo + 1

