    return tuple(people+[i])


def optimize(groups,car,capacity,i):   
    if i == len(groups):
        return 0

    newcar = []
    pos = groups[i].start
    for group in car:
        if group.end > pos:
            newcar.append(group)
        else:
            capacity += group.size

    state = hash(newcar,i)
    try:
        return memo[state]
    except:
        v = optimize(groups,newcar,capacity,i+1) 
        if groups[i].size <= capacity:
            w = optimize(groups,newcar+[groups[i]],capacity-groups[i].size,i+1) + groups[i].value
        else:
            w = 0

        if v > w:
            ie[state] = -1
        elif v < w:
            ie[state] = 1
        else:
            ie[state] = 0

        ans = max(v,w)
        memo[state] = ans
        return ans

