class CircularQueue:
    def __init__(self, k):
        self.q = [None]*k
        self.k = k
        self.front = self.count = 0
    def enqueue(self, val):
        if self.count == self.k:
            return False
        rear = (self.front + self.count) % self.k
        self.q[rear] = val
        self.count += 1
        return True
    def dequeue(self):
        if self.count == 0:
            return None
        val = self.q[self.front]
        self.front = (self.front+1) % self.k
        self.count -= 1
        return val

