class HashChain:
    def __init__(self, size=10):
        self.size = size
        self.buckets = [[] for _ in range(size)]
    def _hash(self, key):
        return hash(key) % self.size
    def insert(self, key, val):
        idx = self._hash(key)
        for pair in self.buckets[idx]:
            if pair[0]==key:
                pair[1]=val
                return
        self.buckets[idx].append([key,val])
    def search(self, key):
        idx = self._hash(key)
        for k,v in self.buckets[idx]:
            if k==key: return v
        return None

class HashOpen:
    def __init__(self, size=10):
        self.size = size
        self.table = [None]*size
    def _hash(self, key):
        return hash(key) % self.size
    def insert(self, key, val):
        idx = self._hash(key)
        for _ in range(self.size):
            if self.table[idx] is None or self.table[idx][0]==key:
                self.table[idx] = (key, val)
                return
            idx = (idx+1) % self.size
    def search(self, key):
        idx = self._hash(key)
        for _ in range(self.size):
            if self.table[idx] is None:
                return None
            if self.table[idx][0]==key:
                return self.table[idx][1]
            idx = (idx+1) % self.size
        return None

