def task_scheduler_wait_time(tasks, cooldown):
    counts = Counter(tasks)
    heap = [-c for c in counts.values()]
    heapq.heapify(heap)
    time = 0
    q = deque()
    while heap or q:
        time += 1
        if heap:
            cnt = -heapq.heappop(heap) - 1
            if cnt > 0:
                q.append((cnt, time + cooldown))
        if q and q[0][1] == time:
            heapq.heappush(heap, -q.popleft()[0])
        if not heap and q:
            time = q[0][1]
    return time

