def eval_postfix(tokens):
    stack = []
    ops = {'+': lambda a,b: a+b, '-': lambda a,b: a-b, '*': lambda a,b: a*b, '/': lambda a,b: int(a/b)}
    for tok in tokens:
        if tok in ops:
            b = stack.pop()
            a = stack.pop()
            stack.append(ops[tok](a,b))
        else:
            stack.append(int(tok))
    return stack[-1]

def infix_to_postfix(expr):
    prec = {'+':1,'-':1,'*':2,'/':2}
    stack = []
    output = []
    for ch in expr:
        if ch.isdigit():
            output.append(ch)
        elif ch == '(':
            stack.append(ch)
        elif ch == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()
        elif ch in prec:
            while stack and stack[-1] != '(' and prec.get(stack[-1],0) >= prec[ch]:
                output.append(stack.pop())
            stack.append(ch)
    while stack:
        output.append(stack.pop())
    return ''.join(output)

